package Q7;
public class RedesignBenchmark{static String oldBuild(int n){String s="";for(int i=0;i<n;i++)s+="field-"+i+";";return s;}static String newBuild(int n){StringBuilder b=new StringBuilder(n*10);for(int i=0;i<n;i++)b.append("field-").append(i).append(';');return b.toString();}static long bench(java.util.function.IntFunction<String>f,int n,int reps){long t=System.nanoTime();int check=0;for(int i=0;i<reps;i++)check+=f.apply(n).length();if(check<0)throw new AssertionError();return System.nanoTime()-t;}public static void main(String[]x){for(int n:new int[]{6,50,500,2000}){int reps=Math.max(10,20000/n);bench(RedesignBenchmark::newBuild,n,100);System.out.println("fields="+n+" old="+bench(RedesignBenchmark::oldBuild,n,reps)+"ns new="+bench(RedesignBenchmark::newBuild,n,reps)+"ns");}}}
